{
  "story": "Recursive feature elimination removes the weakest feature iteratively. Refitting after each drop ensures the remaining feature coefficients update correctly for the next ranking step.",
  "aha": {
    "stateId": "step_refit",
    "observation": "Coefficient weights shift dramatically when a correlated feature is removed, proving that refitting is essential for accurate ranking."
  },
  "layout": {
    "preset": "stepper-compact",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "values": "state.readouts"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "RFE Step",
      "options": ["Full Model", "Drop Weakest", "Refit Weights", "Final Subset"]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "RFE Sequence",
        "regions": [
          {
            "id": "feat_a",
            "label": "Feature A",
            "kind": "feature",
            "values": ["0.85"]
          },
          {
            "id": "feat_b",
            "label": "Feature B",
            "kind": "feature",
            "values": ["0.12"]
          },
          {
            "id": "feat_c",
            "label": "Feature C",
            "kind": "feature",
            "values": ["0.45"]
          }
        ],
        "states": [
          {
            "id": "step_full",
            "label": "Full Model",
            "short": "Fit",
            "sentence": "Fit estimator on all available features.",
            "why": "Establishes baseline coefficients for all variables.",
            "active": ["feat_a", "feat_b", "feat_c"],
            "calloutRegion": "feat_b",
            "readouts": [
              {"id": "score", "label": "R2 Score", "value": "0.88"}
            ]
          },
          {
            "id": "step_drop",
            "label": "Drop Weakest",
            "short": "Drop",
            "sentence": "Identify and remove Feature B with the lowest coefficient.",
            "why": "Removes noise from the feature space.",
            "active": ["feat_b"],
            "calloutRegion": "feat_b",
            "readouts": [
              {"id": "score", "label": "R2 Score", "value": "0.86"}
            ]
          },
          {
            "id": "step_refit",
            "label": "Refit Weights",
            "short": "Refit",
            "sentence": "Refit the model on remaining features A and C.",
            "why": "Uncovers updated coefficients affected by multicollinearity.",
            "active": ["feat_a", "feat_c"],
            "calloutRegion": "feat_a",
            "readouts": [
              {"id": "score", "label": "R2 Score", "value": "0.87"}
            ]
          },
          {
            "id": "step_final",
            "label": "Final Subset",
            "short": "Final",
            "sentence": "Selected optimal subset determined.",
            "why": "Completes iterative elimination loop.",
            "active": ["feat_a", "feat_c"],
            "calloutRegion": "feat_a",
            "readouts": [
              {"id": "score", "label": "R2 Score", "value": "0.87"}
            ]
          }
        ]
      }
    ]
  }
}
